//! The Controls citizen — generated by mobius_codegen.

use egui_citizen::citizen_panel;

use crate::state::{Bench};

citizen_panel!(Controls, "controls");

impl Controls {
    pub fn show(&mut self, ui: &mut egui::Ui, b: &Bench) {
        ui.add_space(3.0);
        ui.vertical(|ui| {
            let mut value = b.enabled.get();
            if ui.checkbox(&mut value, "Enabled").changed() {
                b.enabled.set(value);
            }
            let mut value = b.amplitude.get();
            if ui.add(egui::Slider::new(&mut value, 0.0..=2.0).text("Amplitude")).changed() {
                b.amplitude.set(value);
            }
        });
    }
}
